/* .list 바로 아래 li 만 */
.list > li { color: blue; }

/* h2 바로 다음 p 하나 */
h2 + p { font-weight: bold; }

/* h2 뒤의 모든 형제 p */
h2 ~ p { color: gray; }

.a { margin-bottom: 30px; }
.b { margin-top: 20px; }   /* .a 와 .b 사이 간격은 30px */

* { box-sizing: border-box; }  /* 크기 계산을 쉽게 */

.container {
  display: flex;
  justify-content: space-between; /* 가로: 양 끝 + 사이 균등 */
  align-items: center;            /* 세로: 가운데 */
  gap: 8px;
}
.container .grow { flex: 1; }

.card { position: relative; }
.card .badge {
  position: absolute;  /* .card 기준 */
  top: 8px;
  right: 8px;
}
.header { position: sticky; top: 0; }

const user = { name: "kim" };
user.name = "lee";   // 가능 (내용 변경)
// user = {};        // TypeError (재할당)

if ([]) console.log("빈 배열도 truthy");
console.log(typeof null); // "object"

const a = { info: { n: 1 } };
const b = { ...a };
b.info.n = 2;
console.log(a.info.n); // 2 (안쪽은 공유)

const arr = [1, 2, 3, 4];
const removed = arr.splice(1, 2);
console.log(arr, removed); // [1, 4] [2, 3]

const counter = {
  count: 0,
  start() {
    setTimeout(function () {
      console.log(this.count); // undefined (this = window)
    });
    setTimeout(() => {
      console.log(this.count); // 0 (바깥 start 의 this = counter)
    });
  },
};
counter.start();

const list = document.querySelector("#list");
const li = document.createElement("li");
li.textContent = "새 항목";
list.prepend(li);          // 맨 앞에

li.classList.toggle("done"); // true (붙음)

const form = document.querySelector("form");
form.addEventListener("submit", (event) => {
  event.preventDefault(); // 새로고침 막기
  console.log("직접 처리");
});

// 이벤트 위임
list.addEventListener("click", (e) => {
  if (e.target.matches("li")) e.target.remove();
});

// 주소: /solve.html?set=a&mode=exam#top
console.log(location.search); // "?set=a&mode=exam"
console.log(location.hash);   // "#top"

const params = new URLSearchParams(location.search);
params.get("mode");           // "exam"

console.log(1);
setTimeout(() => console.log(2), 0);
Promise.resolve().then(() => console.log(3));
console.log(4);
// 출력: 1 4 3 2

async function getValue() {
  return 10;
}
const r = getValue(); // Promise
const v = await getValue(); // 10 (async 안이나 모듈 최상단에서)

async function createPost(data) {
  const res = await fetch("/api/posts", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(data),
  });
  if (!res.ok) throw new Error("요청 실패: " + res.status);
  return await res.json();
}

const cart = [{ id: 1, qty: 2 }];
localStorage.setItem("cart", JSON.stringify(cart));

const saved = JSON.parse(localStorage.getItem("cart")) || [];
console.log(saved[0].qty); // 2
